from pathlib import Path
from html.parser import HTMLParser
import json,hashlib
p=Path('products/services/shopify-large-catalogue/release/cited-doc-check.html')
class Links(HTMLParser):
 def __init__(self): super().__init__(); self.links=[]
 def handle_starttag(self,tag,attrs):
  if tag=='a':
   href=dict(attrs).get('href','')
   if '.csv' in href.lower(): self.links.append(href)
x=Links(); x.feed(p.read_text())
r={'source':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'csv_links':list(dict.fromkeys(x.links)),'interpretation':'Links extracted from saved official documentation only; sample contents, reachability and compatibility remain unverified.'}
out=Path('products/services/shopify-large-catalogue/official-sample-delivery/link-discovery.json'); out.parent.mkdir(parents=True,exist_ok=True); out.write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n'); print(out.read_text())
